-- Decoration settings
-- https://wiki.hypr.land/Configuring/Basics/Variables/#decoration

-- Colors generated by wallust. pcall so that a missing or half-written file
-- (wallust rewrites it on every wallpaper change) cannot take this config down.
local ok, c = pcall(require, "wallust.wallust-hyprland")
if not ok then
  -- Fallback palette, used only until wallust regenerates the file.
  c = {
    color0 = "rgb(47484E)",
    color10 = "rgb(604D59)",
    color12 = "rgb(68606A)",
    color15 = "rgb(CABFBF)",
  }
end

hl.config({
  general = {
    border_size = 2,
    gaps_in     = 2,
    gaps_out    = 4,

    col = {
      active_border   = c.color12,
      inactive_border = c.color10,
    },
  },

  decoration = {
    rounding = 10,

    active_opacity     = 1.0,
    inactive_opacity   = 0.96,
    fullscreen_opacity = 1.0,

    dim_inactive = true,
    dim_strength = 0.1,
    dim_special  = 0.8,

    shadow = {
      enabled      = true,
      range        = 3,
      render_power = 1,

      color          = c.color12,
      color_inactive = c.color10,
    },

    blur = {
      enabled           = true,
      size              = 6,
      passes            = 2,
      ignore_opacity    = true,
      new_optimizations = true,
      special           = true,
      popups            = true,
    },
  },

  group = {
    col = {
      border_active = c.color15,
    },

    groupbar = {
      col = {
        active = c.color0,
      },
    },
  },
})
